import type {Point} from './api';

// These are the satellite iframes generated by Google Maps' Share or embed map menu.
const samples = [
  {lat:10.52, lon:7.44, embed:'https://www.google.com/maps/embed?pb=!1m10!1m8!1m3!1d14710.32901369539!2d7.44!3d10.52!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1795134131660!5m2!1sen!2suk'},
  {lat:10.492, lon:7.433, embed:'https://www.google.com/maps/embed?pb=!1m10!1m8!1m3!1d7355.831111196348!2d7.433000000000001!3d10.492!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1795134192354!5m2!1sen!2suk'},
  {lat:10.56, lon:7.46, embed:'https://www.google.com/maps/embed?pb=!1m10!1m8!1m3!1d7354.209167865371!2d7.46!3d10.56!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1795134221365!5m2!1sen!2suk'},
];

export function demoSatellitePoint(point?:Point|null):Point {
  return samples.find(sample=>sample.lat===point?.lat && sample.lon===point.lon) || samples[0];
}

export function googleSatelliteLinks(point:Point, useDemoEmbed:boolean, key?:string) {
  const center=`${point.lat},${point.lon}`;
  const maps=new URL('https://www.google.com/maps/@');
  maps.search=new URLSearchParams({api:'1',map_action:'map',center,zoom:'16',basemap:'satellite'}).toString();
  let embed=useDemoEmbed ? samples.find(sample=>sample.lat===point.lat && sample.lon===point.lon)?.embed : undefined;
  if(!embed && key){
    const url=new URL('https://www.google.com/maps/embed/v1/view');
    url.search=new URLSearchParams({key,center,zoom:'16',maptype:'satellite'}).toString();
    embed=url.href;
  }
  return {maps:maps.href,embed};
}
